BEGIN;
ALTER TABLE task_committees ADD COLUMN is_hr boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX task_one_hr_committee ON task_committees(org_id) WHERE is_hr;
INSERT INTO task_committees(org_id,name,is_hr) SELECT o.id,CASE WHEN EXISTS(SELECT 1 FROM task_committees c WHERE c.org_id=o.id AND c.name='HQ HR') THEN 'HQ HR (Visit Reports ' || gen_random_uuid()::text || ')' ELSE 'HQ HR' END,true FROM organizations o ON CONFLICT DO NOTHING;
CREATE FUNCTION protect_hr_committee() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.is_hr AND (NOT NEW.is_hr OR NEW.archived_at IS NOT NULL) THEN RAISE EXCEPTION 'HQ HR cannot be archived or lose its HR designation'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER hr_committee_fixed BEFORE UPDATE ON task_committees FOR EACH ROW EXECUTE FUNCTION protect_hr_committee();
ALTER TABLE fleet_trip_reports ADD COLUMN private_version integer NOT NULL DEFAULT 0;
ALTER TABLE visit_report_answers ADD COLUMN evaluation jsonb NOT NULL DEFAULT '{"department":"","feedback":""}';
ALTER TABLE visit_report_answers ADD COLUMN is_confidential boolean NOT NULL DEFAULT false;
ALTER TABLE visit_report_events ADD COLUMN visibility text NOT NULL DEFAULT 'shared' CHECK(visibility IN ('shared','hr'));
CREATE FUNCTION protect_report_answer_audience() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE kind text; BEGIN
 SELECT q->>'kind' INTO kind FROM fleet_trip_reports r CROSS JOIN LATERAL jsonb_array_elements(r.template_snapshot->'questions') q WHERE r.id=NEW.report_id AND q->>'id'=NEW.question_id;
 IF kind IS NULL THEN RAISE EXCEPTION 'Question not present in report snapshot'; END IF;
 NEW.is_confidential := kind='confidential';
 IF NEW.is_confidential AND (NEW.task_id IS NOT NULL OR NEW.task_plan->>'kind'<>'none') THEN RAISE EXCEPTION 'Confidential feedback cannot create or link shared tasks'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER report_answer_audience BEFORE INSERT OR UPDATE ON visit_report_answers FOR EACH ROW EXECUTE FUNCTION protect_report_answer_audience();
INSERT INTO visit_report_templates(org_id,key,definition) SELECT id,'hr','{"key": "hr", "name": "HQ Human Resources", "visitTypes": ["Routine Audit & Evaluation", "Employee Engagement Focus", "Grievance / Special Visit"], "sections": [{"id": "section-1", "title": "Employee Engagement, Leadership & Trust Building"}, {"id": "section-2", "title": "Staff Welfare & Living Conditions (Back of House)"}, {"id": "section-3", "title": "Staff Grooming & Professional Conduct"}, {"id": "section-4", "title": "Compliance, Shift Management & Fair Practice"}, {"id": "employee-evaluations", "title": "Monthly Staff Performance Evaluations"}, {"id": "confidential-feedback", "title": "Confidential Employee Feedback \u2014 HQ HR Only"}], "questions": [{"id": "q1", "sectionId": "section-1", "label": "HQ HR Visibility (During Visit)", "guidance": "Document time spent in BOH and on the floor engaging directly with staff, independent of the PIC", "kind": "inspection"}, {"id": "q2", "sectionId": "section-1", "label": "Local Leadership Approachability", "guidance": "Based on observation and staff feedback, is the PIC/2nd IC visible, approachable, and treating staff with fairness and respect?", "kind": "inspection"}, {"id": "q3", "sectionId": "section-1", "label": "Trust Indicators & Escalation Awareness", "guidance": "Do staff feel comfortable bringing grievances to the PIC? Did you verify that staff are aware of how to contact HQ HR directly without fear of retaliation?", "kind": "inspection"}, {"id": "q4", "sectionId": "section-1", "label": "Open Communication Forums", "guidance": "Verify if the PIC is conducting regular departmental or general staff meetings. Is there evidence that staff feel comfortable raising concerns during these local forums?", "kind": "inspection"}, {"id": "q5", "sectionId": "section-1", "label": "Recognition & Motivation", "guidance": "Are staff achievements being actively recognized and celebrated by local management?", "kind": "inspection"}, {"id": "q6", "sectionId": "section-2", "label": "Accommodation Standards", "guidance": "Inspect staff quarters. Are they genuinely comfortable, well-ventilated, pest-free, and respectful of privacy? Are provided beds and linens in good condition?", "kind": "inspection"}, {"id": "q7", "sectionId": "section-2", "label": "Washroom & Shower Facilities", "guidance": "Inspect BOH washrooms. Are they fully functional, hygienic, and regularly cleaned to a high standard?", "kind": "inspection"}, {"id": "q8", "sectionId": "section-2", "label": "Recreation & Break Areas", "guidance": "Evaluate the break area. Is it inviting and providing a genuine space for relaxation away from guest areas?", "kind": "inspection"}, {"id": "q9", "sectionId": "section-2", "label": "Staff Cafeteria & Meals", "guidance": "Evaluate the food quality, nutritional value, and variety. Is the dining area hygienic? Are meal timings respected without operational disruption?", "kind": "inspection"}, {"id": "q10", "sectionId": "section-3", "label": "Uniforms & Presentation", "guidance": "Are staff uniforms clean, well-fitted, and in good repair? Are name tags consistently worn?", "kind": "inspection"}, {"id": "q11", "sectionId": "section-3", "label": "Personal Hygiene", "guidance": "Are high standards of personal grooming enforced by local management across all departments?", "kind": "inspection"}, {"id": "q12", "sectionId": "section-3", "label": "Guest & Peer Interaction", "guidance": "Do staff exhibit professional conduct, a positive attitude, and respect toward both guests and colleagues?", "kind": "inspection"}, {"id": "q13", "sectionId": "section-4", "label": "Shift Optimization (Demand-Based)", "guidance": "Review duty rosters. Is the PIC managing shifts efficiently, aligning them strictly with occupancy and service demands rather than relying on overtime?", "kind": "inspection"}, {"id": "q14", "sectionId": "section-4", "label": "Labor Law Compliance", "guidance": "Verify roster adherence to labor laws: exactly 9 hours per shift inclusive of a 1-hour break, OR 48 hours per week maximum.", "kind": "inspection"}, {"id": "q15", "sectionId": "section-4", "label": "Leave Management", "guidance": "Review the local leave approval process. Is it transparent and fair? Are staff able to utilize entitled leave without friction or favoritism?", "kind": "inspection"}, {"id": "q16", "sectionId": "section-4", "label": "Grievance Documentation", "guidance": "Review any local grievances documented by the PIC. Is there evidence of timely and fair resolution locally before escalating to HQ?", "kind": "inspection"}, {"id": "q17", "sectionId": "section-4", "label": "Statutory Compliance", "guidance": "Verify that necessary labor law notices and safety guidelines are clearly displayed in staff areas.", "kind": "inspection"}, {"id": "score-1", "sectionId": "scorecard", "label": "Local Leadership & Trust", "guidance": "PIC approachability, open communication, recognition", "kind": "score"}, {"id": "score-2", "sectionId": "scorecard", "label": "Staff Welfare (Quarters, Meals, Break Areas)", "guidance": "Comfort, hygiene, food quality maintained locally", "kind": "score"}, {"id": "score-3", "sectionId": "scorecard", "label": "Grooming & Professional Standards", "guidance": "Uniform condition, personal hygiene, peer respect", "kind": "score"}, {"id": "score-4", "sectionId": "scorecard", "label": "Fair Practice (Shift Management, Rosters, Leave)", "guidance": "Demand-based scheduling, adherence to 48hr/week & 9hr/shift rules", "kind": "score"}, {"id": "score-5", "sectionId": "scorecard", "label": "HQ HR Engagement & Escalation Awareness", "guidance": "Staff comfort with HQ HR, knowledge of escalation paths", "kind": "score"}, {"id": "employee-1", "sectionId": "employee-evaluations", "label": "Grooming & Brand Presentation", "guidance": "Maintains impeccable personal hygiene, clean/correct uniform, and professional posture.", "kind": "employee_score"}, {"id": "employee-2", "sectionId": "employee-evaluations", "label": "Shift Compliance & Punctuality", "guidance": "Adheres strictly to the 9-hour shift / 48-hour week rosters; arrives on time and manages duties efficiently without unauthorized overtime.", "kind": "employee_score"}, {"id": "employee-3", "sectionId": "employee-evaluations", "label": "Job Knowledge & Attention to Detail", "guidance": "Demonstrates mastery of departmental SOPs (e.g., spotless housekeeping, precise plating, seamless service, immaculate grounds).", "kind": "employee_score"}, {"id": "employee-4", "sectionId": "employee-evaluations", "label": "Guest Discretion & Intuitive Service", "guidance": "Anticipates guest needs, remains polite, and maintains the peaceful, private atmosphere essential to a boutique villa.", "kind": "employee_score"}, {"id": "employee-5", "sectionId": "employee-evaluations", "label": "Cross-Departmental Teamwork", "guidance": "Exhibits a positive attitude and readily assists other departments when occupancy demands fluctuate.", "kind": "employee_score"}, {"id": "private-feedback", "sectionId": "confidential-feedback", "label": "Key feedback / concerns raised", "guidance": "Record confidential conversations with staff. Use a department or role and omit names when anonymity is requested.", "kind": "confidential"}, {"id": "private-assessment", "sectionId": "confidential-feedback", "label": "HQ HR assessment / recommended action", "guidance": "Record the HR assessment and next steps. These notes are visible only to HQ HR committee members and admins.", "kind": "confidential"}]}'::jsonb FROM organizations ON CONFLICT(org_id,key,version) DO NOTHING;
COMMIT;
